def inject(html, block): return html if block.strip() in html else html.replace('</main>', block + '\n</main>', 1)
def add_schema(html, schema): return html if schema['@type'] in html else html.replace('</head>', '<script type="application/ld+json">'+json.dumps(schema, ensure_ascii=False)+'</script></head>', 1)
def write(path, html):
    p=OUT/path/'index.html'; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(html,encoding='utf-8')

write('hostel-furniture', HUB)
